-- Shared spaghetti ratings schema. Apply using Supabase CLI migrations.
create extension if not exists pgcrypto with schema extensions;
create type public.group_role as enum ('owner','member');
create table public.groups(id uuid primary key default gen_random_uuid(), name text not null check(length(btrim(name)) between 1 and 120), created_at timestamptz not null default now());
create table public.group_members(group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.group_role not null default 'member', display_name text not null check(length(btrim(display_name)) between 1 and 80), created_at timestamptz not null default now(), primary key(group_id,user_id));
create index group_members_user_id_idx on public.group_members(user_id);
create table public.restaurants(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, name text not null check(length(btrim(name)) between 1 and 160), address text not null default '', latitude double precision check(latitude is null or latitude between -90 and 90), longitude double precision check(longitude is null or longitude between -180 and 180), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(group_id,id), check((latitude is null)=(longitude is null)));
create unique index restaurants_group_name_address_key on public.restaurants(group_id,lower(btrim(name)),lower(btrim(address)));
create index restaurants_group_location_idx on public.restaurants(group_id,latitude,longitude);
create table public.ratings(id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, restaurant_id uuid not null, created_by uuid not null references auth.users(id), visited_on date not null, sauce smallint not null check(sauce between 1 and 5), texture smallint not null check(texture between 1 and 5), portion smallint not null check(portion between 1 and 5), enough_cheese boolean not null default false, hot_sauce boolean not null default false, gratinated boolean not null default false, great_location boolean not null default false, hospitality boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), foreign key(group_id,restaurant_id) references public.restaurants(group_id,id) on delete cascade);
create index ratings_group_restaurant_date_idx on public.ratings(group_id,restaurant_id,visited_on desc);
create index ratings_group_created_by_idx on public.ratings(group_id,created_by);
create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
create function private.is_group_member(target_group uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.group_members gm where gm.group_id=target_group and gm.user_id=(select auth.uid())); $$;
create function private.is_group_owner(target_group uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.group_members gm where gm.group_id=target_group and gm.user_id=(select auth.uid()) and gm.role='owner'); $$;
revoke all on function private.is_group_member(uuid) from public,anon;
revoke all on function private.is_group_owner(uuid) from public,anon;
grant execute on function private.is_group_member(uuid) to authenticated;
grant execute on function private.is_group_owner(uuid) to authenticated;
create function public.guard_group_member_update() returns trigger language plpgsql set search_path='' as $$ begin if new.group_id<>old.group_id or new.user_id<>old.user_id or new.role<>old.role or new.created_at<>old.created_at then raise exception 'Only display_name can be changed'; end if; return new; end; $$;
create function public.guard_restaurant_update() returns trigger language plpgsql set search_path='' as $$ begin if new.id<>old.id or new.group_id<>old.group_id or new.created_by<>old.created_by or new.created_at<>old.created_at then raise exception 'Restaurant identity, group, creator and creation time are immutable'; end if; new.updated_at:=now(); return new; end; $$;
create function public.guard_rating_update() returns trigger language plpgsql set search_path='' as $$ begin if new.id<>old.id or new.group_id<>old.group_id or new.created_by<>old.created_by or new.created_at<>old.created_at then raise exception 'Rating identity, group, creator and creation time are immutable'; end if; new.updated_at:=now(); return new; end; $$;
create trigger members_guard_update before update on public.group_members for each row execute function public.guard_group_member_update();
create trigger restaurants_guard_update before update on public.restaurants for each row execute function public.guard_restaurant_update();
create trigger ratings_guard_update before update on public.ratings for each row execute function public.guard_rating_update();
alter table public.groups enable row level security;
alter table public.group_members enable row level security;
alter table public.restaurants enable row level security;
alter table public.ratings enable row level security;
revoke all on public.groups,public.group_members,public.restaurants,public.ratings from public,anon,authenticated;
grant select on public.groups,public.group_members to authenticated;
grant update(display_name) on public.group_members to authenticated;
grant select,insert,update,delete on public.restaurants,public.ratings to authenticated;
grant all on public.groups,public.group_members,public.restaurants,public.ratings to service_role;
create policy groups_read_member on public.groups for select to authenticated using((select private.is_group_member(id)));
create policy members_read_group on public.group_members for select to authenticated using((select private.is_group_member(group_id)));
create policy members_edit_own_name on public.group_members for update to authenticated using(user_id=(select auth.uid()) and (select private.is_group_member(group_id))) with check(user_id=(select auth.uid()) and (select private.is_group_member(group_id)));
create policy restaurants_read_member on public.restaurants for select to authenticated using((select private.is_group_member(group_id)));
create policy restaurants_add_member on public.restaurants for insert to authenticated with check((select private.is_group_member(group_id)) and created_by=(select auth.uid()));
create policy restaurants_edit_member on public.restaurants for update to authenticated using((select private.is_group_member(group_id))) with check((select private.is_group_member(group_id)));
create policy restaurants_remove_owner on public.restaurants for delete to authenticated using((select private.is_group_owner(group_id)));
create policy ratings_read_member on public.ratings for select to authenticated using((select private.is_group_member(group_id)));
create policy ratings_add_self on public.ratings for insert to authenticated with check((select private.is_group_member(group_id)) and created_by=(select auth.uid()));
create policy ratings_edit_self on public.ratings for update to authenticated using((select private.is_group_member(group_id)) and created_by=(select auth.uid())) with check((select private.is_group_member(group_id)) and created_by=(select auth.uid()));
create policy ratings_remove_self_or_owner on public.ratings for delete to authenticated using(created_by=(select auth.uid()) or (select private.is_group_owner(group_id)));

